{
  "title": "The Glass Diver's Rescue",
  "gate_token": "3S5JoRqbcD9hKLuvWFh5RA",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city outskirts.",
      "visual_description": "Crumbling stone walls draped with torn royal banners, a dark archway ahead, and the glass diver adjusting his helmet in the dim light.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "Mara unrolls a cracked map near the city gates.",
      "visual_description": "Mara traces a route on a faded parchment with ink-stained fingers, the tin fox peering over her shoulder, the oracle lamp casting a tiny glow on the paper.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's flame eye flickers urgently as it faces a twisted tower with black windows, shadows writhing inside.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "They find a sleeping tax collector blocking a passage.",
      "visual_description": "A figure slumped against a crumbling wall, using a ledger as a pillow, papers with official stamps scattered around, snoring softly.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The tin fox scouts ahead through a narrow alley.",
      "visual_description": "The small metal fox with a key-wind tail moves silently between fallen stones, blue glass eyes scanning for danger.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "They encounter a frightened townsman hiding in a doorway.",
      "visual_description": "A pale figure in tattered clothes cowers under a stone arch, pointing a trembling hand toward the castle gates.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The glass diver peers through a window into a guarded courtyard.",
      "visual_description": "Through a cracked glass pane, the diver sees armored figures patrolling near an iron door, his helmet reflecting the scene.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Mara marks a secret route on her map with a brass compass.",
      "visual_description": "Mara kneels, compass in hand, drawing a line on the map while the oracle lamp hovers nearby, its flame steady.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver swims through a mirror to bypass a locked gate.",
      "visual_description": "The diver's reflection ripples as he steps into a tall mirror, coat shimmering, disappearing into silver depths.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "They discover an old royal banner torn and hanging at an angle.",
      "visual_description": "A faded banner with a crest snaps in the wind from a broken flagpole, casting a long shadow over the cobblestones.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The oracle lamp illuminates a magic door covered in runes.",
      "visual_description": "A stone door etched with glowing symbols pulses as the lamp's light touches it, revealing a hidden handle.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "The sleeping tax collector wakes briefly and stamps a random paper.",
      "visual_description": "Bleary-eyed, the collector fumbles for a stamp, presses it onto a scrap, then slumps back to sleep, head on the ledger.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "The tin fox leads them through a hidden passage behind a tapestry.",
      "visual_description": "The fox pushes aside a moth-eaten tapestry, revealing a narrow stone corridor, its blue eyes glowing in the dark.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "They reach the inner courtyard where a treasure chest sits on a pedestal.",
      "visual_description": "A gilded chest under a shaft of light, surrounded by armored statues holding rusted halberds.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver retrieves a key from inside the chest using his mirror technique.",
      "visual_description": "The diver's hand passes through the chest's reflection, emerging with a brass key, his helmet fogging briefly.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols close in as they flee toward a bridge.",
      "visual_description": "Heavy footsteps echo behind them as the group sprints across a wide stone bridge, banners flapping overhead.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge begins to collapse as they near the far side.",
      "visual_description": "Cracks spider across the stone, chunks falling into a chasm below, the group leaping from crumbling blocks.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the safety of a misty forest beyond the bridge.",
      "visual_description": "The party stands at the treeline, looking back at the ruined city through the fog, the bridge now a broken gap.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

